                p:[-width*tailWidth/100,-height*tail/100]
            },
            {
                p:[width*tailWidth/100,-height*tail/100],
                out:[width/squeeze,-height*tail/(squeeze*100)]
            },
            {
                in:[width,-ch], // *tail/100
                p:[width,0],
                out:[width,ch]
            },
            {
                in:[cw,height],
                p:[0,height],
                out:[-cw,height]
            },
            {
                in:[-width,ch],
                p:[-width,0],
                out:[-width,-ch] // *tail/100
            },
            {closed:true}
        ];
    } else {
        return [
            {
                in:[-width/squeeze,-height*tail/(squeeze*100)],
                p:[0,-height*tail/100],
                out:[width/squeeze,-height*tail/(squeeze*100)]
            },
            {
                in:[width,-ch], // *tail/100
                p:[width,0],
                out:[width,ch]
            },
            {
                in:[cw,height],
                p:[0,height],
                out:[-cw,height]
            },
            {
                in:[-width,ch],
                p:[-width,0],
                out:[-width,-ch] // *tail/100
            },
            {closed:true}
        ];
    }
}

function getHandles(params) {
    return {
        p1: params.p1,
        p2: params.p2,
        p3: params.p3
    }
}

function getPath(params) {
    return [
        [params.p1.x,params.p1.y],
        [params.p2.x,params.p2.y],
        [params.p3.x,params.p3.y],
        {closed:params.closed}
    ];
}

function getHandles(params) {
    let lineWidth = params.lineWidth;
    let end = params.end;
    let start = params.start;
    let dx = end.x-start.x;
    let dy = end.y-start.y;
    let dlen = Math.hypot(dx,dy);
    let nx = dx / dlen;
    let ny = dy / dlen;
    let cwX = -dy / dlen;
    let cwY = dx / dlen;
    let ccwX = dy / dlen;
    let ccwY = -dx / dlen;
    return {
        s: params.start,
        e: params.end,
        lw: {
            x: start.x + cwX * lineWidth + dx/3,
            y: start.y + cwY * lineWidth + dy/3,
            axis:[cwX,cwY]
        }
    }
}

function getPath(params) {
    let lineWidth = params.lineWidth;
    let end = params.end;
    let start = params.start;
    let dx = end.x-start.x;
    let dy = end.y-start.y;
    let dlen = Math.hypot(dx,dy);
    let nx = dx / dlen;
    let ny = dy / dlen;
    let cwX = -dy / dlen;
    let cwY = dx / dlen;
    let ccwX = dy / dlen;
    let ccwY = -dx / dlen;
    return [
        [start.x + cwX * lineWidth, start.y + cwY * lineWidth],
        [start.x + ccwX * lineWidth, start.y + ccwY * lineWidth],
        [end.x + ccwX * lineWidth, end.y + ccwY * lineWidth],
        [end.x + cwX * lineWidth, end.y + cwY * lineWidth],
        {closed:true}
    ];
}
